dleplugin.mysqlinstall:
CREATE TABLE IF NOT EXISTS {prefix}_dbmovies_films ( id INT(11) NOT NULL AUTO_INCREMENT, tmdb_id INT(11) NOT NULL, post_id INT(11) NOT NULL, title VARCHAR(255) NOT NULL, original_title VARCHAR(255), overview TEXT, poster_path VARCHAR(255), backdrop_path VARCHAR(255), release_date DATE, vote_average DECIMAL(3,1), vote_count INT(11), popularity DECIMAL(10,3), runtime INT(11), status VARCHAR(50), genres TEXT, cast TEXT, date_added TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, date_updated TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY (tmdb_id), KEY (post_id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS {prefix}_dbmovies_settings ( id INT(11) NOT NULL AUTO_INCREMENT, api_key VARCHAR(255) NOT NULL, language VARCHAR(10) DEFAULT 'tr-TR', poster_quality VARCHAR(20) DEFAULT 'w500', category_id INT(11) DEFAULT 0, last_update TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO {prefix}_admin_sections (name, title, icon, allow_groups) VALUES ('dbmovies', 'DbMovies Film Ekleme', 'fa-film', '1');

